import sys

def max_tandem_repeat_length(s, k):
    n = len(s)
    max_length = 0

    # Check all possible lengths of the original tandem repeat
    for length in range(1, n + 1):
        if n % length == 0:
            period = n // length
            is_tandem = True
            for i in range(length):
                for j in range(1, period):
                    if s[i] != s[i + j * length]:
                        is_tandem = False
                        break
                if not is_tandem:
                    break
            if is_tandem:
                max_length = max(max_length, length * (period + k // length))

    return max_length

