    n = len(s)
    max_length = 0

    # Check all possible periods
    for p in range(1, n + 1):
        if n % p == 0:
            period = n // p
            is_tandem = True
            for i in range(p):
                for j in range(1, period):
                    if s[i] != s[i + j * p]:
                        is_tandem = False
                        break
                if not is_tandem:
                    break
            if is_tandem:
                # Calculate the maximum length of the tandem repeat
                max_length = max(max_length, p * (period + k // p))

    # Check if we can form a new tandem repeat with the added characters
    for i in range(n):
